      input.permissions === undefined &&
      input.graceDays === undefined &&
      input.pot === undefined &&
      input.parent === undefined &&
      input.fiscalStartMonth === undefined &&
      input.alertThreshold === undefined
    )
      return;
    once(() => save.mutateAsync(input));
  };

