                        + " WHERE SHEET_ID = " + id);
            }
            for (String table : poolTables(c)) {
                s.execute("CREATE TABLE " + schema + "." + q(table) + " AS SELECT * FROM PUBLIC." + q(table)
                        + " WHERE POOL_ID IN (SELECT ID FROM PUBLIC.POOL WHERE SHEET_ID = " + id + ")");
