                s.execute("CREATE VIEW " + LIVE + "." + q(table) + " AS SELECT * FROM PUBLIC." + q(table));
                s.execute("CREATE TABLE " + EMPTY + "." + q(table) + " AS SELECT * FROM PUBLIC." + q(table)
                        + " WITH NO DATA");
